'use strict';
Business.importReceipt=async function(){const d=await this.load();let preview=null,context=null;this.open('Excel 批量入库 · 整批原子提交',`<p>下载标准模板填写，最多500捆/512KB。全部行校验成功后才能保存草稿；独立审核确认整单入库。不接受无提示的部分成功。</p><button id="receipt-template" class="button secondary">下载 Excel 标准模板</button><form id="receipt-import-form" class="user-form"><div class="form-grid"><label>项目<select id="import-project">${this.options(d.projects,null,'name')}</select></label><label>货权客户<select id="import-customer">${this.options(d.customers.filter(c=>c.active),null,'name')}</select></label></div><label>Excel 文件<input id="import-file" type="file" accept=".xlsx" required></label><button class="button primary">校验并预览</button></form><div id="import-result" role="status"></div><button id="import-save" class="button primary" disabled>保存整批草稿（不增加库存）</button>`);
 $('receipt-template').onclick=async()=>{try{const r=await API.request('/receipts/template',{binary:true});const a=document.createElement('a'),url=URL.createObjectURL(r.blob);a.href=url;a.download='穆松尼入库模板.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){notify(e.message);}};
 for(const id of ['import-project','import-customer','import-file'])$(id).onchange=()=>{preview=null;$('import-save').disabled=true;$('import-result').textContent='选择已变化，请重新预览。';};
 $('receipt-import-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;$('import-save').disabled=true;preview=null;try{const f=$('import-file').files[0];if(!f||f.size>524288||!f.name.toLowerCase().endsWith('.xlsx'))throw Error('请选择512KB以下的标准 .xlsx');const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));context={project_id:$('import-project').value,customer_id:$('import-customer').value};const result=await API.request('/receipts/import-preview',{method:'POST',body:{...context,file_base64:btoa(binary)}});if(!result.valid){$('import-result').innerHTML='<p class="error">整批未通过，未创建单据：</p><ul>'+result.errors.map(x=>`<li>Excel 第 ${x.row} 行：${esc(x.message)}</li>`).join('')+'</ul>';return;}preview=result.lines;$('import-result').innerHTML='<p>全部 '+preview.length+' 捆校验通过，尚未写入库存。</p><div class="business-table"><table><thead><tr><th>捆包号</th><th>毛重（吨）</th><th>包装（吨）</th><th>净重（吨）</th><th>生产日期</th></tr></thead><tbody>'+preview.map(l=>`<tr><td>${esc(l.bundle_no)}</td><td>${esc(l.gross_weight)}</td><td>${esc(l.packaging_weight)}</td><td>${esc(l.net_weight)}</td><td>${esc(l.production_date)}</td></tr>`).join('')+'</tbody></table></div>';$('import-save').disabled=false;}catch(err){$('import-result').textContent=err.message;}finally{e.submitter.disabled=false;}};
 $('import-save').onclick=async e=>{if(!preview)return;e.target.disabled=true;try{const r=await API.request('/receipts',{method:'POST',body:{...context,origin:'EXCEL',lines:preview}});await this.receiptDetail(r.id);notify('整批草稿已保存；请提交独立审核。');}catch(err){$('import-result').textContent=err.message;e.target.disabled=false;}};
};
